1	import * as THREE from "three";
2	import { makeNoise3D, makeFbm } from "./noise.js";
3	
4	// ---- small color helpers (work in 0..255 int rgb) ----
5	function lerp(a, b, t) { return a + (b - a) * t; }
6	function mix(c1, c2, t) {
7	  return [
8	    lerp(c1[0], c2[0], t),
9	    lerp(c1[1], c2[1], t),
10	    lerp(c1[2], c2[2], t),
11	  ];
12	}
13	
14	// A brand-purple ocean world with a few GOLD islands. These are rendered as
15	// real metal (high metalness, low roughness) so they shimmer — the albedo here
16	// is gold's warm reflectance tint, anchored on the brand gold (#F5C440).
17	// [height, rgb].
18	const LAND_STOPS = [
19	  [0.00, [214, 158, 58]],  // deep gold shore
20	  [0.30, [245, 196, 64]],  // brand gold
21	  [0.60, [250, 212, 104]], // bright gold
22	  [0.85, [255, 226, 148]], // pale gold highland
23	  [1.00, [255, 240, 205]], // cream frost cap
24	];
25	
26	function rampLand(t) {
27	  for (let i = 0; i < LAND_STOPS.length - 1; i++) {
28	    const [h0, c0] = LAND_STOPS[i];
29	    const [h1, c1] = LAND_STOPS[i + 1];
30	    if (t <= h1) {
31	      const k = (t - h0) / (h1 - h0 || 1);
32	      return mix(c0, c1, Math.max(0, Math.min(1, k)));
33	    }
34	  }
35	  return LAND_STOPS[LAND_STOPS.length - 1][1];
36	}
37	
38	const DEEP = [43, 45, 110];      // deep brand purple (--color-purple-glow)
39	const SHALLOW = [107, 95, 212];   // brand purple shallows (--color-purple)
40	const SNOW = [240, 238, 248];     // frost (--color-text-primary)
41	
42	// Shared landform constants so the texture bake and the elevation sampler below
43	// agree on exactly where land is.
44	const CONTINENT_FREQ = 1.5; // continent scale (lower = larger, calmer landforms)
45	const DEFAULT_SEA_LEVEL = 0.64;
46	
47	/**
48	 * Build a sampler that returns the planet's surface elevation (0..1) for a
49	 * lat/lon, using the *same* fbm field and frequency as the baked texture — so a
50	 * hotspot placed where `isLand` is true lands on visible gold, not the sea.
51	 */
52	export function createElevationSampler({ seed = 7 } = {}) {
53	  const noise = makeNoise3D(seed);
54	  const fbm = makeFbm(noise, { octaves: 4, lacunarity: 2.0, gain: 0.45 });
55	
56	  function elevationAt(latDeg, lonDeg) {
57	    const lat = (latDeg * Math.PI) / 180;
58	    const lon = (lonDeg * Math.PI) / 180;
59	    const cosLat = Math.cos(lat);
60	    const sx = cosLat * Math.cos(lon);
61	    const sy = Math.sin(lat);
62	    const sz = cosLat * Math.sin(lon);
63	    const h = fbm(sx * CONTINENT_FREQ, sy * CONTINENT_FREQ, sz * CONTINENT_FREQ);
64	    return h * 0.5 + 0.5;
65	  }
66	
67	  return {
68	    elevationAt,
69	    isLand(latDeg, lonDeg, seaLevel = DEFAULT_SEA_LEVEL) {
70	      return elevationAt(latDeg, lonDeg) >= seaLevel;
71	    },
72	    /**
73	     * Scan a coarse lat/lon grid (avoiding the icy poles) and return land spots
74	     * sorted by elevation, highest first — a good pick for an island that reads
75	     * clearly above the sea.
76	     */
77	    findLandSpots({ seaLevel = DEFAULT_SEA_LEVEL, latLimit = 60, step = 4 } = {}) {
78	      const spots = [];
79	      for (let lat = -latLimit; lat <= latLimit; lat += step) {
80	        for (let lon = -180; lon < 180; lon += step) {
81	          const h = elevationAt(lat, lon);
82	          if (h >= seaLevel) spots.push({ lat, lon, h });
83	        }
84	      }
85	      spots.sort((a, b) => b.h - a.h);
86	      return spots;
87	    },
88	  };
89	}
90	
91	/**
92	 * Bake equirectangular color / bump / roughness maps for the planet, plus a
93	 * separate cloud alpha map. Heavy-ish loop (~2M px) — run behind the loader.
94	 */
95	export function generatePlanetTextures({
96	  seed = 7,
97	  width = 2048,
98	  height = 1024,
99	  seaLevel = DEFAULT_SEA_LEVEL, // high → mostly ocean, just a few islands
100	} = {}) {
101	  const noise = makeNoise3D(seed);
102	  // Few octaves + gentle gain → large, smooth landforms (no busy speckle).
103	  const fbm = makeFbm(noise, { octaves: 4, lacunarity: 2.0, gain: 0.45 });
104	  // Second low-freq field for soft color variation in the sea.
105	  const noise2 = makeNoise3D(seed * 131 + 17);
106	  const fbm2 = makeFbm(noise2, { octaves: 3, lacunarity: 2.2, gain: 0.5 });
107	
108	  const color = document.createElement("canvas");
109	  const bump = document.createElement("canvas");
110	  const rough = document.createElement("canvas");
111	  const metal = document.createElement("canvas");
112	  for (const c of [color, bump, rough, metal]) { c.width = width; c.height = height; }
113	
114	  const cImg = color.getContext("2d").createImageData(width, height);
115	  const bImg = bump.getContext("2d").createImageData(width, height);
116	  const rImg = rough.getContext("2d").createImageData(width, height);
117	  const mImg = metal.getContext("2d").createImageData(width, height);
118	  const cD = cImg.data, bD = bImg.data, rD = rImg.data, mD = mImg.data;
119	
120	  // Precompute per-column longitude sin/cos.
121	  const cosLon = new Float32Array(width);
122	  const sinLon = new Float32Array(width);
123	  for (let x = 0; x < width; x++) {
124	    const lon = (x / width) * Math.PI * 2 - Math.PI;
125	    cosLon[x] = Math.cos(lon);
126	    sinLon[x] = Math.sin(lon);
127	  }
128	
129	  const freq = CONTINENT_FREQ; // continent scale (lower = larger, calmer landforms)
130	
131	  for (let y = 0; y < height; y++) {
132	    const lat = Math.PI / 2 - (y / height) * Math.PI;
133	    const cosLat = Math.cos(lat);
134	    const sy = Math.sin(lat);
135	    const latAbs = Math.abs(lat) / (Math.PI / 2); // 0 eq -> 1 pole
136	
137	    for (let x = 0; x < width; x++) {
138	      const sx = cosLat * cosLon[x];
139	      const sz = cosLat * sinLon[x];
140	
141	      // Smooth base elevation in 0..1 — no sharpening, so coasts stay soft.
142	      let h = fbm(sx * freq, sy * freq, sz * freq);
143	      h = h * 0.5 + 0.5;
144	
145	      // Gentle low-freq variation to keep the sea from looking flat.
146	      const tide = fbm2(sx * 1.6 + 11, sy * 1.6, sz * 1.6 - 7) * 0.5 + 0.5;
147	
148	      // Soft polar frost; subtle so it reads as haze, not a hard cap.
149	      const iceEdge = 0.78;
150	      const ice = Math.max(0, (latAbs - iceEdge) / (1 - iceEdge)) * 0.7;
151	
152	      let r, g, b, elev, roughness, metalness;
153	
154	      if (h < seaLevel) {
155	        // Purple sea, gently depth-graded; smooth for a soft specular sheen.
156	        const depth = h / seaLevel; // 0 deep .. 1 coast
157	        const col = mix(DEEP, SHALLOW, Math.pow(depth, 1.2) * (0.85 + tide * 0.3));
158	        r = col[0]; g = col[1]; b = col[2];
159	        elev = 0.45;
160	        roughness = lerp(0.55, 0.8, depth); // matte → no white env sheen
161	        metalness = 0.0; // water is not metal
162	      } else {
163	        // Gold island, rendered as polished metal so it shimmers in the light.
164	        const t = (h - seaLevel) / (1 - seaLevel); // 0 coast .. 1 peak
165	        let col = rampLand(t);
166	        const coast = Math.min(1, t / 0.12); // fade in over the first sliver
167	        col = mix([SHALLOW[0], SHALLOW[1], SHALLOW[2]], col, coast);
168	        r = col[0]; g = col[1]; b = col[2];
169	        elev = 0.5 + t * 0.4;
170	        // Low roughness + a little micro-variation = bright, shifting glints.
171	        roughness = lerp(0.34, 0.18, t) + (tide - 0.5) * 0.08;
172	        roughness = Math.max(0.1, Math.min(0.6, roughness));
173	        metalness = 0.92 * coast; // misty shoreline eases out of full metal
174	      }
175	
176	      // Soft frost haze near the poles (matte, non-metallic).
177	      if (ice > 0) {
178	        const k = Math.min(1, ice);
179	        r = lerp(r, SNOW[0], k);
180	        g = lerp(g, SNOW[1], k);
181	        b = lerp(b, SNOW[2], k);
182	        roughness = lerp(roughness, 0.55, k);
183	        metalness = lerp(metalness, 0.0, k);
184	      }
185	
186	      const i = (y * width + x) * 4;
187	      cD[i] = r; cD[i + 1] = g; cD[i + 2] = b; cD[i + 3] = 255;
188	
189	      const bv = elev * 255;
190	      bD[i] = bv; bD[i + 1] = bv; bD[i + 2] = bv; bD[i + 3] = 255;
191	
192	      const mv = metalness * 255;
193	      mD[i] = mv; mD[i + 1] = mv; mD[i + 2] = mv; mD[i + 3] = 255;
194	
195	      const rv = roughness * 255;
196	      rD[i] = rv; rD[i + 1] = rv; rD[i + 2] = rv; rD[i + 3] = 255;
197	    }
198	  }
199	
200	  color.getContext("2d").putImageData(cImg, 0, 0);
201	  bump.getContext("2d").putImageData(bImg, 0, 0);
202	  rough.getContext("2d").putImageData(rImg, 0, 0);
203	  metal.getContext("2d").putImageData(mImg, 0, 0);
204	
205	  // ---- clouds: lower-res, wispy alpha from a separate fbm field ----
206	  const cw = 1024, ch = 512;
207	  const cloud = document.createElement("canvas");
208	  cloud.width = cw; cloud.height = ch;
209	  const clImg = cloud.getContext("2d").createImageData(cw, ch);
210	  const clD = clImg.data;
211	  const cn = makeNoise3D(seed * 977 + 3);
212	  const cfbm = makeFbm(cn, { octaves: 5, lacunarity: 2.4, gain: 0.55 });
213	  for (let y = 0; y < ch; y++) {
214	    const lat = Math.PI / 2 - (y / ch) * Math.PI;
215	    const cl = Math.cos(lat), sl = Math.sin(lat);
216	    for (let x = 0; x < cw; x++) {
217	      const lon = (x / cw) * Math.PI * 2 - Math.PI;
218	      const px = cl * Math.cos(lon), pz = cl * Math.sin(lon);
219	      let v = cfbm(px * 2.4, sl * 2.4, pz * 2.4) * 0.5 + 0.5;
220	      // Threshold into wisps.
221	      v = Math.max(0, (v - 0.52) / 0.48);
222	      v = Math.pow(v, 1.3);
223	      const i = (y * cw + x) * 4;
224	      clD[i] = 255; clD[i + 1] = 255; clD[i + 2] = 255;
225	      clD[i + 3] = Math.min(255, v * 255);
226	    }
227	  }
228	  cloud.getContext("2d").putImageData(clImg, 0, 0);
229	
230	  const tex = (canvas, srgb) => {
231	    const t = new THREE.CanvasTexture(canvas);
232	    t.colorSpace = srgb ? THREE.SRGBColorSpace : THREE.NoColorSpace;
233	    t.anisotropy = 8;
234	    t.wrapS = THREE.RepeatWrapping;
235	    return t;
236	  };
237	
238	  return {
239	    colorMap: tex(color, true),
240	    bumpMap: tex(bump, false),
241	    roughnessMap: tex(rough, false),
242	    metalnessMap: tex(metal, false),
243	    cloudMap: tex(cloud, true),
244	  };
245	}
