1	import * as THREE from "three";
2	
3	// Procedural radial band texture for the ring: bright-purple and pale-lavender
4	// bands with varying opacity and a couple of clear gaps (à la Cassini).
5	function makeRingTexture() {
6	  const w = 1024, h = 2;
7	  const c = document.createElement("canvas");
8	  c.width = w; c.height = h;
9	  const ctx = c.getContext("2d");
10	  const img = ctx.createImageData(w, h);
11	  const d = img.data;
12	
13	  const PALE = [216, 212, 248];    // pale lavender band
14	  const PURPLE = [139, 127, 232];  // brand purple-bright band (#8B7FE8)
15	
16	  for (let x = 0; x < w; x++) {
17	    const u = x / w; // 0 inner .. 1 outer
18	
19	    // Layered bands.
20	    let a =
21	      0.55 +
22	      0.25 * Math.sin(u * 90) +
23	      0.15 * Math.sin(u * 230 + 1.3) +
24	      0.12 * Math.sin(u * 37 + 0.6);
25	    a = Math.max(0, Math.min(1, a));
26	
27	    // Clear gaps (divisions).
28	    const gap = (center, width) =>
29	      Math.max(0, 1 - Math.exp(-((u - center) ** 2) / (2 * width * width)));
30	    a *= gap(0.42, 0.012);
31	    a *= gap(0.68, 0.018);
32	
33	    // Fade the very inner and outer edges to nothing.
34	    a *= Math.min(1, u / 0.06) * Math.min(1, (1 - u) / 0.12);
35	
36	    const tint = 0.5 + 0.5 * Math.sin(u * 60 + 2.0);
37	    const col = [
38	      PALE[0] * (1 - tint) + PURPLE[0] * tint,
39	      PALE[1] * (1 - tint) + PURPLE[1] * tint,
40	      PALE[2] * (1 - tint) + PURPLE[2] * tint,
41	    ];
42	
43	    for (let y = 0; y < h; y++) {
44	      const i = (y * w + x) * 4;
45	      d[i] = col[0]; d[i + 1] = col[1]; d[i + 2] = col[2];
46	      d[i + 3] = a * 235;
47	    }
48	  }
49	  ctx.putImageData(img, 0, 0);
50	  const t = new THREE.CanvasTexture(c);
51	  t.colorSpace = THREE.SRGBColorSpace;
52	  t.anisotropy = 8;
53	  return t;
54	}
55	
56	/**
57	 * Flat Saturn-style ring. Returns a mesh lying in the planet's equatorial
58	 * plane — add it to the planetGroup so it shares the axial tilt.
59	 */
60	export function makeRing(planetRadius, {
61	  inner = planetRadius * 1.35,
62	  outer = planetRadius * 2.25,
63	} = {}) {
64	  const geo = new THREE.RingGeometry(inner, outer, 256, 1);
65	
66	  // Remap UVs so the texture runs radially (u = normalized radius), letting the
67	  // 1D band texture paint concentric bands instead of RingGeometry's default.
68	  const pos = geo.attributes.position;
69	  const uv = geo.attributes.uv;
70	  const v = new THREE.Vector3();
71	  for (let i = 0; i < pos.count; i++) {
72	    v.fromBufferAttribute(pos, i);
73	    const r = v.length();
74	    uv.setXY(i, (r - inner) / (outer - inner), 0.5);
75	  }
76	  uv.needsUpdate = true;
77	
78	  const mat = new THREE.MeshBasicMaterial({
79	    map: makeRingTexture(),
80	    transparent: true,
81	    side: THREE.DoubleSide,
82	    depthWrite: false,
83	    opacity: 0.92,
84	  });
85	
86	  const ring = new THREE.Mesh(geo, mat);
87	  ring.rotation.x = -Math.PI / 2; // lie flat in the equatorial plane
88	  return ring;
89	}
