/* Ghost CTA — same angled anatomy as the primary, teal outline treatment
   ("LEADERBOARD"). clip-path clips a real border away, so the outline is the
   button's teal background showing 1px around a dark inner layer (::after).
   The slant mirrors the primary so the pair bookends the row. */
.ts-item.ts-cta-ghost {
  position: relative;
  padding: 16px 44px;
  font-size: clamp(15px, 1.4vw, 19px);
  font-weight: 700;
  letter-spacing: var(--tracking-wide);
  color: var(--color-accent);
  background: var(--color-accent);
  border: none;
  border-radius: var(--radius-sm);
  clip-path: polygon(0% 0%, calc(100% - 10px) 0%, 100% 100%, 10px 100%);
  opacity: 1;
}
.ts-item.ts-cta-ghost::after {
  content: "";
  position: absolute;
  inset: 1px;
  z-index: -1;
  background: #101226;
  clip-path: polygon(0% 0%, calc(100% - 10px) 0%, 100% 100%, 10px 100%);
  transition: background 0.15s ease;
}
.ts-item.ts-cta-ghost:hover,
.ts-item.ts-cta-ghost.is-selected {
  color: var(--color-accent);
  background: var(--color-accent);
}
.ts-item.ts-cta-ghost:hover::after,
.ts-item.ts-cta-ghost.is-selected::after { background: #0f2f2b; }
.ts-item.ts-cta-ghost:active::after { background: #164039; }
.ts-item.ts-cta-ghost.is-selected::before { content: none; }

